window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3efccce85a35dd69"]={"versions": [{"id": "FIG-3efccce85a35dd69", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Adaptive Platform (Application Design, Port Interface). Das Diagramm stellt die Vererbungshierarchie für REST-basierte Service-Schnittstellen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code>: Abstrakte Basisklasse für Schnittstellen (kursiv formatiert), versehen mit den Stereotypen bzw. Metaklassen-Eigenschaften <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>. Sie besitzt ein separates, leeres Attributfach.</li>\n<li><code>RestServiceInterface</code>: Konkrete Metaklasse zur Repräsentation einer REST-Service-Schnittstelle, ebenfalls mit einem separaten, leeren Attributfach dargestellt.</li>\n<li>Generalisierungsbeziehung: <code>RestServiceInterface</code> erbt über einen geschlossenen, nicht ausgefüllten Vererbungspfeil von <code>PortInterface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein rein statisches Metamodell ohne Verhaltens- oder Sequenzaspekte. Dynamische Interaktionen (wie HTTP-REST-Aufrufe zwischen Software-Komponenten) ergeben sich zur Laufzeit über Ports, die durch <code>RestServiceInterface</code> typisiert sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>RestServiceInterface</code> leitet sich von <code>PortInterface</code> ab und dient als Metaklasse zur Typisierung von <code>PortPrototype</code>-Elementen für REST-basierte Webservice-Kommunikation. Durch die Spezialisierung erbt es die Eigenschaften von <code>PortInterface</code>, <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> und bildet die vertragliche Basis für Schnittstellen eines <code>ApplicationSwComponentType</code>.</p>"}, {"id": "FIG-9f3b8dbd84ed2737", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Adaptive Platform (Application Design, Port Interface). Das Diagramm stellt die Vererbungshierarchie für REST-basierte Service-Schnittstellen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code>: Abstrakte Basisklasse für Schnittstellen (kursiv formatiert), versehen mit den Stereotypen bzw. Metaklassen-Eigenschaften <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>. Sie besitzt ein separates, leeres Attributfach.</li>\n<li><code>RestServiceInterface</code>: Konkrete Metaklasse zur Repräsentation einer REST-Service-Schnittstelle, ebenfalls mit einem separaten, leeren Attributfach dargestellt.</li>\n<li>Generalisierungsbeziehung: <code>RestServiceInterface</code> erbt über einen geschlossenen, nicht ausgefüllten Vererbungspfeil von <code>PortInterface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein rein statisches Metamodell ohne Verhaltens- oder Sequenzaspekte. Dynamische Interaktionen (wie HTTP-REST-Aufrufe zwischen Software-Komponenten) ergeben sich zur Laufzeit über Ports, die durch <code>RestServiceInterface</code> typisiert sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>RestServiceInterface</code> leitet sich von <code>PortInterface</code> ab und dient als Metaklasse zur Typisierung von <code>PortPrototype</code>-Elementen für REST-basierte Webservice-Kommunikation. Durch die Spezialisierung erbt es die Eigenschaften von <code>PortInterface</code>, <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> und bildet die vertragliche Basis für Schnittstellen eines <code>ApplicationSwComponentType</code>.</p>"}, {"id": "FIG-9b58a37b84b0d43c", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Adaptive Platform (Application Design, Port Interface). Das Diagramm stellt die Vererbungshierarchie für REST-basierte Service-Schnittstellen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>PortInterface</code>: Abstrakte Basisklasse für Schnittstellen (kursiv formatiert), versehen mit den Stereotypen bzw. Metaklassen-Eigenschaften <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>, dargestellt als ungeteiltes Klassenelement ohne separates Attributfach.</li>\n<li><code>RestServiceInterface</code>: Konkrete Metaklasse zur Repräsentation einer REST-Service-Schnittstelle, dargestellt als ungeteiltes Klassenelement ohne separates Attributfach.</li>\n<li>Generalisierungsbeziehung: <code>RestServiceInterface</code> erbt über einen geschlossenen, nicht ausgefüllten Vererbungspfeil von <code>PortInterface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein rein statisches Metamodell ohne Verhaltens- oder Sequenzaspekte. Dynamische Interaktionen (wie HTTP-REST-Aufrufe zwischen Software-Komponenten) ergeben sich zur Laufzeit über Ports, die durch <code>RestServiceInterface</code> typisiert sind.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>RestServiceInterface</code> leitet sich von <code>PortInterface</code> ab und dient als Metaklasse zur Typisierung von <code>PortPrototype</code>-Elementen für REST-basierte Webservice-Kommunikation. Durch die Spezialisierung erbt es die Eigenschaften von <code>PortInterface</code>, <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> und bildet die vertragliche Basis für Schnittstellen eines <code>ApplicationSwComponentType</code>.</p>"}], "trans": [{"from": "FIG-3efccce85a35dd69", "to": "FIG-9f3b8dbd84ed2737", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9f3b8dbd84ed2737", "to": "FIG-9b58a37b84b0d43c", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>RestServiceInterface, PortInterface: Wegfall der horizontalen Trennlinie zwischen Namens- und Attributfach in beiden UML-Klassenfeldern.</li>\n</ul>"}]};
